func testFormatter(t *testing.T, buf *bytes.Buffer) Formatter {
	t.Helper()
	return func(entry Context) {
		modules, scopes := entry.Modules()
		buf.WriteString(strings.Join(modules, "."))
		if len(scopes) > 0 {
			last := scopes[len(scopes)-1]
			if last != "" {
				buf.WriteString("@")
				buf.WriteString(last)
			}
		}
		buf.WriteString(" | ")
		buf.WriteString(entry.Level().String())
		buf.WriteString(" | ")
		buf.WriteString(entry.Message())
		if entry.HasError() {
			buf.WriteString(": ")
			buf.WriteString(entry.Error().Error())
		}
		global, local := entry.Attributes()
		for _, a := range global {
			buf.WriteString(" | ")
			buf.WriteString(a.Name)
		}
		for _, a := range local {
			buf.WriteString(" | ")
			buf.WriteString(a.Name)
		}
		if entry.HasStackTrace() {
			buf.WriteString(" | stack")
		}
		buf.WriteByte('\n')
	}
}

