func TestAcquireBuffer_FreeBuffer(t *testing.T) {
	b := AcquireBuffer()
	if b == nil {
		t.Fatal("AcquireBuffer returned nil")
	}
	if cap(*b) != PooledBufferSize {
		t.Errorf("buffer cap = %d, want %d", cap(*b), PooledBufferSize)
	}

	*b = append(*b, "hello"...)
	FreeBuffer(b)

	b2 := AcquireBuffer()
	if b2 == nil {
		t.Fatal("second AcquireBuffer returned nil")
	}
	if len(*b2) != 0 {
		t.Error("acquired buffer should be empty")
	}

	// Cleanup: free the second buffer too
	FreeBuffer(b2)
}

