func TestFreeBuffer_RejectsOversized(t *testing.T) {
	b := AcquireBuffer()
	// force expansion beyond PooledBufferSize
	for range PooledBufferSize + 1 {
		*b = append(*b, 'x')
	}
	FreeBuffer(b)

	b2 := AcquireBuffer()
	if b2 == nil {
		t.Fatal("AcquireBuffer returned nil after oversized reject")
	}
	FreeBuffer(b2)
}

